package com.agacostays.payroll.consumer; import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import lombok.extern.slf4j.Slf4j; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; @Component @Slf4j public class AttendanceMarkedEventConsumer{private final ObjectMapper mapper;public AttendanceMarkedEventConsumer(ObjectMapper m){mapper=m;}@KafkaListener(topics="attendance.events",groupId="payroll-attendance")public void consume(String msg){try{JsonNode n=mapper.readTree(msg);log.debug("Attendance event received staffId={}",n.has("staffId")?n.get("staffId").asLong():null);}catch(Exception e){log.error("Attendance event error",e);}}}